        Member member = loadMember(memberId);
        member.unsuspend();
        saveMemberPort.saveMember(member);
        return member;
    }

    private Member loadMember(UUID memberId) {
        return loadMemberPort.loadMember(memberId)
                .orElseThrow(() -> new MemberNotFoundException(memberId));
