import com.example.lending.domain.Member;
import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.Id;
import jakarta.persistence.Table;

import java.util.UUID;

@Entity
@Table(name = "member")
class MemberJpaEntity {

    @Id
    private UUID id;

    @Column(nullable = false)
    private String name;

    @Column(nullable = false)
    private boolean suspended;

    protected MemberJpaEntity() {
    }

    static MemberJpaEntity from(Member member) {
        MemberJpaEntity entity = new MemberJpaEntity();
        entity.id = member.getId();
        entity.name = member.getName();
        entity.suspended = member.isSuspended();
        return entity;
    }

    Member toDomain() {
        return Member.reconstitute(id, name, suspended);
    }
}
