import java.util.UUID;

@Component
public class AuditPersistenceAdapter implements RecordAuditPort, LoadAuditPort {

    private final AuditRecordJpaRepository auditRecordJpaRepository;

    public AuditPersistenceAdapter(AuditRecordJpaRepository auditRecordJpaRepository) {
        this.auditRecordJpaRepository = auditRecordJpaRepository;
    }

    @Override
    public void recordAudit(AuditRecord record) {
        auditRecordJpaRepository.save(AuditRecordJpaEntity.from(record));
    }

    @Override
    public List<AuditRecord> loadAuditRecords(UUID targetId) {
        return auditRecordJpaRepository.findByTargetIdOrderByOccurredAtAscIdAsc(targetId).stream()
                .map(AuditRecordJpaEntity::toDomain)
                .toList();
    }
}
