package com.example.lending.adapter.out.persistence;

import com.example.lending.domain.AuditAction;
import com.example.lending.domain.AuditRecord;
import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.EnumType;
import jakarta.persistence.Enumerated;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.Index;
import jakarta.persistence.Table;

import java.time.Instant;
import java.util.UUID;

@Entity
@Table(name = "audit_record", indexes = @Index(columnList = "targetId"))
class AuditRecordJpaEntity {

    // 같은 시각에 기록된 항목도 기록 순서대로 정렬하기 위한 증가 키.
    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Enumerated(EnumType.STRING)
    @Column(nullable = false)
    private AuditAction action;

    @Column(nullable = false)
    private UUID targetId;

    private UUID memberId;

    @Column(nullable = false)
    private Instant occurredAt;

    protected AuditRecordJpaEntity() {
    }

    static AuditRecordJpaEntity from(AuditRecord record) {
        AuditRecordJpaEntity entity = new AuditRecordJpaEntity();
        entity.action = record.getAction();
        entity.targetId = record.getTargetId();
        entity.memberId = record.getMemberId();
        entity.occurredAt = record.getOccurredAt();
        return entity;
    }

    AuditRecord toDomain() {
        return AuditRecord.reconstitute(action, targetId, memberId, occurredAt);
    }
}
