package com.example.lending.domain;

import java.time.Instant;
import java.util.Objects;
import java.util.UUID;

// 상태를 바꾸는 작업 한 건의 감사 기록. 대상(targetId)은 작업마다 다르다:
// 대출·반납은 대출 ID, 폐기는 책 ID, 정지·해제는 회원 ID.
public class AuditRecord {

    private final AuditAction action;
    private final UUID targetId;
    private final UUID memberId;
    private final Instant occurredAt;

    private AuditRecord(AuditAction action, UUID targetId, UUID memberId, Instant occurredAt) {
        this.action = Objects.requireNonNull(action, "action");
        this.targetId = Objects.requireNonNull(targetId, "targetId");
        this.memberId = memberId;
        this.occurredAt = Objects.requireNonNull(occurredAt, "occurredAt");
    }

    public static AuditRecord loan(Loan loan, Instant occurredAt) {
        return new AuditRecord(AuditAction.LOAN, loan.getId(), loan.getMemberId(), occurredAt);
    }

    public static AuditRecord returnOf(Loan loan, Instant occurredAt) {
        return new AuditRecord(AuditAction.RETURN, loan.getId(), loan.getMemberId(), occurredAt);
    }

    // 폐기·정지·해제는 작업을 한 회원을 알 수 없으므로 memberId 가 null 이다.
    public static AuditRecord discard(Book book, Instant occurredAt) {
        return new AuditRecord(AuditAction.DISCARD, book.getId(), null, occurredAt);
    }

    public static AuditRecord suspend(Member member, Instant occurredAt) {
        return new AuditRecord(AuditAction.SUSPEND, member.getId(), null, occurredAt);
    }

    public static AuditRecord unsuspend(Member member, Instant occurredAt) {
        return new AuditRecord(AuditAction.UNSUSPEND, member.getId(), null, occurredAt);
    }

    public static AuditRecord reconstitute(AuditAction action, UUID targetId, UUID memberId, Instant occurredAt) {
        return new AuditRecord(action, targetId, memberId, occurredAt);
    }

    public AuditAction getAction() {
        return action;
    }

    public UUID getTargetId() {
        return targetId;
    }

    public UUID getMemberId() {
        return memberId;
    }

    public Instant getOccurredAt() {
        return occurredAt;
    }
}
